import{c as o,Q as d,j as t,m as c}from"./chunks/framework.BXc4yaFE.js";const g=JSON.parse('{"title":"Claude Code W28–W31 新功能（v2.1.202–v2.1.221）","description":"","frontmatter":{},"headers":[],"relativePath":"research/best-practices/48-w28-w31-features.md","filePath":"research/best-practices/48-w28-w31-features.md","lastUpdated":1785909234000}'),r={name:"research/best-practices/48-w28-w31-features.md"};function i(s,e,a,l,n,u){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="claude-code-w28–w31-新功能-v2-1-202–v2-1-221" tabindex="-1">Claude Code W28–W31 新功能（v2.1.202–v2.1.221） <a class="header-anchor" href="#claude-code-w28–w31-新功能-v2-1-202–v2-1-221" aria-label="Permalink to &quot;Claude Code W28–W31 新功能（v2.1.202–v2.1.221）&quot;">​</a></h1><blockquote><p>來源：<a href="https://github.com/anthropics/claude-code/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">anthropics/claude-code CHANGELOG</a>（v2.1.202 – v2.1.221） 期間：2026-07-05 ~ 2026-08-03 整理日期：2026-08-04</p></blockquote><hr><h2 id="_1-模型" tabindex="-1">1. 模型 <a class="header-anchor" href="#_1-模型" aria-label="Permalink to &quot;1. 模型&quot;">​</a></h2><ul><li><strong>Claude Opus 5（<code>claude-opus-5</code>）上線，1M context window</strong>（v2.1.219）。詳見 <code>44-claude-opus-5.md</code>。</li><li>Auto mode 的分類器對外部 session 預設改用 <strong>Sonnet 5</strong>（v2.1.210）。</li><li>Vertex AI 重新啟用 tool search（Claude 4.5 世代以後的模型，v2.1.213）。</li><li>transcript 現在<strong>逐則記錄該訊息的 reasoning effort</strong>（v2.1.212）；<code>subagentStatusLine</code> payload 也帶 effort（v2.1.214）。</li></ul><hr><h2 id="_2-subagent-背景-session-的治理-本期最大變化" tabindex="-1">2. Subagent / 背景 session 的治理（本期最大變化） <a class="header-anchor" href="#_2-subagent-背景-session-的治理-本期最大變化" aria-label="Permalink to &quot;2. Subagent / 背景 session 的治理（本期最大變化）&quot;">​</a></h2><blockquote><p>主軸：<strong>把「無界扇出」關掉，把背景 agent 的收尾語義補上。</strong></p></blockquote><table tabindex="0"><thead><tr><th>變更</th><th>版本</th><th>內容</th></tr></thead><tbody><tr><td>每 session subagent 上限</td><td>v2.1.212</td><td>預設 200，<code>CLAUDE_CODE_MAX_SUBAGENTS_PER_SESSION</code> 可調；<code>/clear</code> 重置</td></tr><tr><td>同時執行 subagent 上限</td><td>v2.1.217</td><td>預設 20，<code>CLAUDE_CODE_MAX_CONCURRENT_SUBAGENTS</code> 可調</td></tr><tr><td><strong>預設不再巢狀 spawn</strong></td><td>v2.1.217</td><td>subagent 不再生 subagent；要更深需設 <code>CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH</code></td></tr><tr><td>預算真正止血</td><td>v2.1.217</td><td><code>--max-budget-usd</code> 達標後拒絕新 spawn <strong>並中止執行中的背景 agent</strong>（先前無效）</td></tr><tr><td>WebSearch 上限</td><td>v2.1.212</td><td>每 session 預設 200 次，<code>CLAUDE_CODE_MAX_WEB_SEARCHES_PER_SESSION</code> 可調</td></tr><tr><td>Task 工具 <code>mode</code> 參數<strong>廢除</strong></td><td>v2.1.212</td><td>現已忽略；subagent 預設繼承 parent 的 permission mode</td></tr><tr><td><code>/fork</code> 語義改變</td><td>v2.1.212–213</td><td><code>/fork</code> = 把對話複製成<strong>獨立背景 session</strong>（自有 worktree）；原本的 in-session subagent 改名 <code>/subtask</code></td></tr><tr><td>背景 session 收尾</td><td>v2.1.205 → v2.1.213</td><td>commit + push 保存工作；<strong>只在任務需要時才開 draft PR</strong>；遵守你的 CLAUDE.md git 指示；結束時一定回報工作落在哪</td></tr><tr><td><code>context: fork</code> skill</td><td>v2.1.218</td><td>預設改為背景執行，可用 <code>background: false</code> 個別退出</td></tr><tr><td>MCP 長工具呼叫</td><td>v2.1.212</td><td>超過 2 分鐘自動轉背景，<code>CLAUDE_CODE_MCP_AUTO_BACKGROUND_MS</code> 可調</td></tr><tr><td>Worktree 隔離修正</td><td>v2.1.203/210/216</td><td>修掉 worktree-isolated subagent 用 <code>git -C</code> / <code>--git-dir</code> / <code>GIT_DIR</code> 把 git 指回主 checkout 的三個路徑</td></tr></tbody></table><p><strong>對本 workspace 的影響</strong>：<code>fusion</code> / <code>multi-mode-skill</code> 的委派假設需重讀——巢狀委派預設關閉、<code>mode</code> 參數失效、背景 session 會自行 commit/push（<code>core.md</code> Git 鐵律的「使用者明示不 commit」須寫進 CLAUDE.md 才會被遵守）。</p><hr><h2 id="_3-自動觸發的收斂-驗證與研究改為手動" tabindex="-1">3. 自動觸發的收斂：驗證與研究改為手動 <a class="header-anchor" href="#_3-自動觸發的收斂-驗證與研究改為手動" aria-label="Permalink to &quot;3. 自動觸發的收斂：驗證與研究改為手動&quot;">​</a></h2><ul><li><strong>v2.1.215</strong>：Claude 不再自行跑 <code>/verify</code> 與 <code>/code-review</code>，要用就自己打。</li><li><strong>v2.1.218</strong>：<code>/deep-research</code> 同樣改為只在手動呼叫時啟動。</li><li><strong>v2.1.218</strong>：<code>/code-review ultra</code> 在非互動 session 不再靜默降級成本地審查，改為啟動雲端審查。</li><li><strong>v2.1.202</strong>：<code>/review</code> 改為快速單趟審查。</li><li><strong><code>/ultrareview</code>（新指令，雲端深審）</strong> 本期大量修正：接受 <code>#123</code> / <code>PR 123</code> / PR URL、會 fetch 遠端分支並在打錯時建議相近分支名、<code>/clear</code> 後仍要求計費確認、無 merge base 時改為提議審查全部 tracked 檔、diff 過大時顯示上限/實測大小/最大貢獻檔。</li></ul><p><strong>判讀</strong>：官方正在把「驗證什麼時候跑」的決定權從模型手上收回 harness。本 workspace 的 TEST 閘門本來就由規則與 hook 驅動，方向一致；但任何「靠模型自動 review」的假設要作廢。</p><hr><h2 id="_4-權限與沙箱-安全修正密集期" tabindex="-1">4. 權限與沙箱（安全修正密集期） <a class="header-anchor" href="#_4-權限與沙箱-安全修正密集期" aria-label="Permalink to &quot;4. 權限與沙箱（安全修正密集期）&quot;">​</a></h2><p><strong>Bash / PowerShell 權限繞過修正</strong>（v2.1.213/214/216）：</p><ul><li>zsh 在 <code>[[ ]]</code> 條件式中執行隱藏命令 → 現在會提示</li><li>檔案描述子重導向形式 → 改為 <strong>fail closed</strong></li><li><strong>超過 10,000 字元的命令一律提示</strong>，不再自動執行</li><li><code>help</code> / <code>man</code> 的危險選項、<code>file</code> 的 <code>-m</code>/<code>-f</code>、<code>docker</code>（含 Podman shim）的 daemon 重導向旗標（<code>--url</code>/<code>--connection</code>/<code>--identity</code>）→ 改為需要授權</li><li>Windows PowerShell 5.1 的權限檢查繞過、含引號路徑、隱形 Unicode 字元 → 修正</li><li>非 ASCII 字元的 shell 詞界解析 → 對齊真實 shell</li></ul><p><strong>權限規則語義變更（會改變既有設定行為）</strong>（v2.1.214）：</p><blockquote><p>單段 <code>dir/**</code> 的 <strong>allow</strong> 規則（如 <code>Edit(src/**)</code>）與 hook <code>if:</code> 條件，現在只匹配 <code>&lt;cwd&gt;/dir</code>，不再匹配樹中任意深度的同名目錄。要任意深度請寫 <code>**/dir/**</code>。<code>deny</code>/<code>ask</code> 規則維持任意深度匹配。</p></blockquote><p><strong>沙箱</strong>：</p><ul><li><code>sandbox.credentials</code> 新增 <code>mode: &quot;mask&quot;</code>（Linux/WSL，v2.1.213）：沙箱內讀到哨兵副本，proxy 在對外時才換回真值；macOS 退回 <code>deny</code></li><li><code>sandbox.network.strictAllowlist</code>（v2.1.219）</li><li><code>sandbox.filesystem.disabled</code>（v2.1.216）：只保留網路出口管制，跳過檔案系統隔離</li></ul><p><strong>其他硬化</strong>：</p><ul><li><code>.claude</code> / <code>.claude/worktrees</code> 的 symlink 逃逸（workflow 儲存、排程任務寫入、worktree 建立）→ 修正（v2.1.212/216）</li><li><code>/rewind</code> 不再經 symlink/hard link 還原或刪檔，並回報跳過幾個路徑（v2.1.216）</li><li>agent frontmatter hooks 需該 agent 檔所在資料夾已接受 workspace trust（v2.1.218）</li><li>auto mode 新增「封鎖竄改 session transcript 檔」規則（v2.1.205）；對未解析變數的 <code>rm -rf</code> 會先問（v2.1.205）</li><li>啟動時對<strong>過寬的 permission 規則</strong>發出警告（v2.1.210）；permission 規則改存在 repo 根目錄，跨 worktree 持久（v2.1.211）</li><li>新增 <strong>EndConversation 工具</strong>：Claude 可終止極端濫用或越獄嘗試的 session（v2.1.214）</li><li>修正 permission preview 未中和特定 Unicode 字元導致核可訊息視覺被改寫（v2.1.211）</li></ul><hr><h2 id="_5-context-cache-記憶" tabindex="-1">5. Context / cache / 記憶 <a class="header-anchor" href="#_5-context-cache-記憶" aria-label="Permalink to &quot;5. Context / cache / 記憶&quot;">​</a></h2><ul><li><strong>prompt caching</strong>：mid-conversation system block 現在在 LLM gateway 與自訂 base URL（Bedrock / Vertex / 1P）後方也生效（v2.1.212）</li><li>auto-mode 權限檢查改為<strong>重用已快取的對話前綴</strong>，降低 cache 成本（v2.1.213）</li><li><code>/context</code> 超出視窗時顯示明確警告；<code>/compact</code> 失敗顯示為錯誤（v2.1.216）</li><li>修正 Opus 4.8 on Bedrock 從不觸發 auto-compact（v2.1.217）</li><li>memory frontmatter 加 ISO <code>modified</code> 時戳（v2.1.214）；memory 值在行內 <code>#</code> 被截斷 → 修正（v2.1.214）</li><li>記憶索引警告改為只量測<strong>實際載入</strong>的內容（v2.1.211）</li><li><code>SendMessage</code> 內文不再重複灌進 replay 歷史與 tool result，降低 inter-agent 訊息 token（v2.1.212）</li><li>長 session 訊息正規化的二次方成本 → 修正（v2.1.216）</li><li>Stats 面板納入 cache token，並分列 input / output / cache read / cache write（v2.1.213）</li></ul><hr><h2 id="_6-工具鏈與企業治理" tabindex="-1">6. 工具鏈與企業治理 <a class="header-anchor" href="#_6-工具鏈與企業治理" aria-label="Permalink to &quot;6. 工具鏈與企業治理&quot;">​</a></h2><ul><li><strong><code>claude-api</code> skill 新增 <code>prompt-audit</code> 子命令</strong>（v2.1.213）：稽核 prompt 與 tool description 是否還帶著為舊世代模型寫的模式——與 <code>46-context-engineering-claude5.md</code> 同一問題意識</li><li><code>/doctor</code> 會提出 <code>CLAUDE.md</code> 精簡建議（v2.1.206）</li><li>Dynamic workflow size 設定（控制 agent 數量）＋ <code>workflow.run_id</code> / <code>workflow.name</code> OTel 屬性（v2.1.202）</li><li>OTel：<code>message.uuid</code> / <code>client_request_id</code> / <code>tool_source</code> 屬性（v2.1.214）、<code>CLAUDE_CODE_OTEL_CONTENT_MAX_LENGTH</code>（預設 60 KB 截斷）、managed settings 的 <code>OTEL_EXPORTER_OTLP_ENDPOINT</code> 現在統管所有 signal（v2.1.217）</li><li>Enterprise <code>forceLoginMethod</code> 擴及 VS Code extension / SDK / <code>setup-token</code> / <code>install-github-app</code>（v2.1.212）</li><li>Auto mode 在 Bedrock / Vertex / Foundry 免 opt-in（v2.1.207）</li><li>修正排程任務把自己設定的 prompt 當成不可信輸入而拒絕執行（v2.1.214）</li><li>修正 hook exit code 2 在 stdout JSON schema 驗證失敗時不阻斷（v2.1.214）；hook 逾時被誤報為使用者拒絕（v2.1.210）</li><li>修正 <code>continue:false</code> hook 的中止在工具失敗或中途完成時被丟棄（v2.1.212）</li></ul><hr><h2 id="_7-介面" tabindex="-1">7. 介面 <a class="header-anchor" href="#_7-介面" aria-label="Permalink to &quot;7. 介面&quot;">​</a></h2><ul><li>Focus view 切換 <code>Ctrl+Alt+F</code>：把工具活動收進可展開的每輪摘要（v2.1.221）</li><li>Screen reader mode（<code>--ax-screen-reader</code>）與刪字朗讀（v2.1.208/218）</li><li><code>/resume</code> 在 agent view 開啟過往 session 選單（含已從清單刪除者），選中即以背景 session 恢復（v2.1.212）</li><li><code>/status</code> 顯示 session 種類：<code>interactive</code> / 背景 <code>attached</code> / <code>unattended</code>（v2.1.213）</li><li>emoji shortcode 自動補全（v2.1.217，<code>emojiCompletionEnabled</code> 可關）</li><li>左方向鍵誤丟對話 → 編輯後按下會先確認（v2.1.218）</li></ul><hr><h2 id="_8-升級後建議重驗的本-workspace-假設" tabindex="-1">8. 升級後建議重驗的本 workspace 假設 <a class="header-anchor" href="#_8-升級後建議重驗的本-workspace-假設" aria-label="Permalink to &quot;8. 升級後建議重驗的本 workspace 假設&quot;">​</a></h2><ol><li><code>Edit(src/**)</code> 類<strong>單段 allow 規則</strong>的匹配範圍已縮小 → 檢查 <code>settings.json</code> 與 hook <code>if:</code> 條件</li><li>巢狀 subagent 預設關閉 → <code>fusion</code> / <code>multi-mode-skill</code> 的多層委派設計</li><li>Task 工具 <code>mode</code> 參數失效 → 依賴它切 permission mode 的地方改用 parent 模式繼承</li><li>背景 session 會自動 commit/push → CLAUDE.md 的 git 指示成為唯一約束來源，須寫明</li><li><code>/verify</code>、<code>/code-review</code>、<code>/deep-research</code> 不再自動觸發 → 驗證流程必須由規則、hook 或 SKILL 明確呼叫</li></ol><hr><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to &quot;延伸閱讀&quot;">​</a></h2><ul><li><code>42-w26-27-features.md</code> — 前一期（v2.1.185–201）</li><li><code>44-claude-opus-5.md</code> · <code>46-context-engineering-claude5.md</code> · <code>47-verification-loops-skills.md</code></li><li><code>12-permissions.md</code> · <code>13-sandbox.md</code> — 權限與沙箱基礎（本期變更是其增量）</li></ul>',39)])])}const m=o(r,[["render",i]]);export{g as __pageData,m as default};
